<?php
namespace App\Services\Automation;use App\Models\Organization;use Ramsey\Uuid\Uuid;
class AutomationTriggerEngine{public function __construct(private AutomationExecutionService $executions){}public function dispatch(Organization $org,string $type,array $context,?string $correlationId=null):array{$query=$org->automations()->where('enabled',true)->where('status','active')->whereHas('triggers',fn($q)=>$q->where('type',$type));$results=[];foreach($query->with(['triggers','conditions','actions','organization.users'])->get() as $automation){$trigger=$automation->triggers->first();if(isset($trigger->configuration['deviceId'])&&(string)$trigger->configuration['deviceId']!==(string)($context['deviceId']??''))continue;if(isset($trigger->configuration['field'])&&$trigger->configuration['field']!==($context['field']??null))continue;try{$derived=$correlationId?(string)Uuid::uuid5(Uuid::NAMESPACE_URL,$correlationId.':'.$automation->id):null;$results[]=$this->executions->execute($automation,$type,$context,$derived);}catch(\App\Exceptions\FeatureNotAvailableException){continue;}}return $results;}}
